    {
      "@type": "FAQPage",
      "@id": "https://www.stselectronicrecyclinginc.com/bakersfield-ca#faqpage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "What areas do you serve?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS serves Bakersfield, Kern County, and organizations throughout California through scheduled commercial pickup programs. Service planning can account for equipment volume, access requirements, site count, and preferred collection timing."
          }
        },
        {
          "@type": "Question",
          "name": "Is pickup free?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Pickup is available at no cost for qualifying volumes and projects. Contact STS with the equipment type, approximate quantity, origin site, and timing so the team can review available options."
          }
        },
        {
          "@type": "Question",
          "name": "Do you provide audit documentation?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. STS can provide documentation covering collected equipment, chain of custody, processing activity, and project disposition. Reporting details vary by project, so organizations should identify inventory and audit needs during scheduling."
          }
        },
        {
          "@type": "Question",
          "name": "What happens after pickup?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Equipment is staged, evaluated, and directed through appropriate processing or recovery pathways. Data-bearing devices can receive documented handling based on the selected service, while recoverable materials are routed for responsible downstream processing."
          }
        },
        {
          "@type": "Question",
          "name": "Can schools and healthcare organizations use the service?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Schools, colleges, clinics, hospitals, and public agencies can coordinate electronics recycling around calendars, facility access, privacy procedures, and equipment refresh schedules."
          }
        },
        {
          "@type": "Question",
          "name": "What standards may guide data handling?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Project requirements may reference NIST 800-88 for media sanitization, HIPAA for protected health information, or internal security policies. STS can discuss documentation and handling options with the organization responsible for the equipment."
          }
        }
      ]
